# ========================================# =============== 审阅看板页 ===============# ========================================import osimport jsonimport timeimport shutilfrom typing import List, Dict, Anyfrom umi_log import loggerfrom .page import Page  # 页基类from ..utils.utils import allowedFileNameclass ReviewBoard(Page):    def __init__(self, *args):        super().__init__(*args)        self.review_data_path = os.path.join(os.path.expanduser("~"), "Umi-OCR", "review_board.json")        self.review_data = self.load_review_data()        self.current_filter = {}        self.current_sort = ("timestamp", "desc")        # 初始化数据目录        self.init_data_directory()    def init_data_directory(self):        """初始化数据目录"""        data_dir = os.path.dirname(self.review_data_path)        if not os.path.exists(data_dir):            os.makedirs(data_dir)    def load_review_data(self) -> List[Dict]:        """加载审阅看板数据"""        try:            if os.path.exists(self.review_data_path):                with open(self.review_data_path, "r", encoding="utf-8") as f:                    return json.load(f)            else:                return []        except Exception as e:            logger.error(f"加载审阅数据失败: {str(e)}")            return []    def save_review_data(self):        """保存审阅看板数据"""        try:            with open(self.review_data_path, "w", encoding="utf-8") as f:                json.dump(self.review_data, f, ensure_ascii=False, indent=2)            logger.debug(f"审阅数据已保存: {self.review_data_path}")        except Exception as e:            logger.error(f"保存审阅数据失败: {str(e)}")    def add_ocr_result(self, result: Dict):        """添加OCR结果到审阅看板"""        # 构建审阅记录        review_item = {            "id": f"{int(time.time() * 1000)}_{id(result)}",            "timestamp": int(time.time()),            "source_path": result.get("dir", "") + os.sep + result.get("fileName", ""),            "thumbnail_path": self.generate_thumbnail(result),            "text_content": result.get("data", ""),            "confidence": result.get("confidence", 0.0),            "status": "未处理",  # 未处理/已校对/待修改/已完成            "tags": [],            "assignee": "",            "comments": ""        }        # 添加到审阅数据        self.review_data.insert(0, review_item)        # 保存数据        self.save_review_data()        return review_item    def generate_thumbnail(self, result: Dict) -> str:        """生成缩略图路径"""        # 这里需要根据实际情况实现缩略图生成        # 暂时返回原图路径        return result.get("dir", "") + os.sep + result.get("fileName", "")    def update_review_item(self, item_id: str, updates: Dict):        """更新审阅项"""        for item in self.review_data:            if item["id"] == item_id:                item.update(updates)                self.save_review_data()                return True        return False    def delete_review_item(self, item_id: str):        """删除审阅项"""        self.review_data = [item for item in self.review_data if item["id"] != item_id]        self.save_review_data()    def batch_update_items(self, item_ids: List[str], updates: Dict):        """批量更新审阅项"""        for item_id in item_ids:            self.update_review_item(item_id, updates)    def batch_delete_items(self, item_ids: List[str]):        """批量删除审阅项"""        for item_id in item_ids:            self.delete_review_item(item_id)    def get_filtered_items(self, filters: Dict = None, sort: tuple = None) -> List[Dict]:        """获取过滤和排序后的审阅项"""        if filters is None:            filters = self.current_filter        if sort is None:            sort = self.current_sort        # 应用过滤        filtered_items = self.review_data        for key, value in filters.items():            if value:                if key == "status":                    filtered_items = [item for item in filtered_items if item[key] == value]                elif key == "assignee":                    filtered_items = [item for item in filtered_items if value in item[key]]                elif key == "tags":                    filtered_items = [item for item in filtered_items if any(tag in item[key] for tag in value)]                elif key == "search":                    filtered_items = [item for item in filtered_items if value.lower() in item["text_content"].lower() or value.lower() in item["source_path"].lower()]        # 应用排序        sort_key, sort_order = sort        if sort_key in ["timestamp", "confidence"]:            filtered_items = sorted(filtered_items, key=lambda x: x[sort_key], reverse=sort_order == "desc")        elif sort_key in ["status", "assignee"]:            filtered_items = sorted(filtered_items, key=lambda x: x[sort_key], reverse=sort_order == "desc")        return filtered_items    def export_as_markdown(self, items: List[Dict], export_path: str):        """导出为Markdown报告"""        try:            with open(export_path, "w", encoding="utf-8") as f:                f.write(f"# 审阅看板报告\n")                f.write(f"生成时间: {time.strftime(r'%Y-%m-%d %H:%M:%S', time.localtime())}\n")                f.write(f"记录数量: {len(items)}\n\n")                for item in items:                    f.write(f"## 记录ID: {item['id']}\n")                    f.write(f"- 来源路径: {item['source_path']}\n")                    f.write(f"- 时间戳: {time.strftime(r'%Y-%m-%d %H:%M:%S', time.localtime(item['timestamp']))}\n")                    f.write(f"- 置信度: {item['confidence']:.2f}\n")                    f.write(f"- 状态: {item['status']}\n")                    f.write(f"- 负责人: {item['assignee']}\n")                    f.write(f"- 标签: {', '.join(item['tags']) if item['tags'] else '无'}\n")                    f.write(f"- 备注: {item['comments'] if item['comments'] else '无'}\n")                    f.write(f"\n**识别文本:**\n")                    f.write(f"{item['text_content']}\n\n")            logger.info(f"Markdown报告已导出: {export_path}")            return True        except Exception as e:            logger.error(f"导出Markdown报告失败: {str(e)}")            return False    def export_as_html(self, items: List[Dict], export_path: str):        """导出为HTML报告"""        try:            with open(export_path, "w", encoding="utf-8") as f:                f.write("<!DOCTYPE html>\n")                f.write("<html lang='zh-CN'>\n")                f.write("<head>\n")                f.write("<meta charset='UTF-8'>\n")                f.write("<title>审阅看板报告</title>\n")                f.write("<style>\n")                f.write("body { font-family: Arial, sans-serif; margin: 20px; }\n")                f.write("h1 { color: #333; }\n")                f.write("h2 { color: #666; border-bottom: 1px solid #ccc; padding-bottom: 5px; }\n")                f.write("p { margin: 5px 0; }\n")                f.write(".item-info { margin: 10px 0; padding: 10px; border: 1px solid #eee; border-radius: 5px; }\n")                f.write(".item-text { background-color: #f5f5f5; padding: 10px; border-radius: 5px; margin-top: 10px; }\n")                f.write("</style>\n")                f.write("</head>\n")                f.write("<body>\n")                f.write(f"<h1>审阅看板报告</h1>\n")                f.write(f"<p>生成时间: {time.strftime(r'%Y-%m-%d %H:%M:%S', time.localtime())}</p>\n")                f.write(f"<p>记录数量: {len(items)}</p>\n\n")                for item in items:                    f.write(f"<h2>记录ID: {item['id']}</h2>\n")                    f.write(f"<div class='item-info'>\n")                    f.write(f"<p><strong>来源路径:</strong> {item['source_path']}</p>\n")                    f.write(f"<p><strong>时间戳:</strong> {time.strftime(r'%Y-%m-%d %H:%M:%S', time.localtime(item['timestamp']))}</p>\n")                    f.write(f"<p><strong>置信度:</strong> {item['confidence']:.2f}</p>\n")                    f.write(f"<p><strong>状态:</strong> {item['status']}</p>\n")                    f.write(f"<p><strong>负责人:</strong> {item['assignee']}</p>\n")                    f.write(f"<p><strong>标签:</strong> {', '.join(item['tags']) if item['tags'] else '无'}</p>\n")                    f.write(f"<p><strong>备注:</strong> {item['comments'] if item['comments'] else '无'}</p>\n")                    f.write(f"</div>\n")                    f.write(f"<div class='item-text'>\n")                    f.write(f"<strong>识别文本:</strong><br>\n")                    f.write(f"{item['text_content'].replace('\n', '<br>')}\n")                    f.write(f"</div>\n\n")                f.write("</body>\n")                f.write("</html>\n")            logger.info(f"HTML报告已导出: {export_path}")            return True        except Exception as e:            logger.error(f"导出HTML报告失败: {str(e)}")            return False    # ========================= 【qml调用python】 =========================    def get_review_items(self, filters: Dict = None, sort: tuple = None) -> List[Dict]:        """获取审阅项列表"""        return self.get_filtered_items(filters, sort)    def add_ocr_result_from_qml(self, result: Dict) -> Dict:        """从qml添加OCR结果"""        return self.add_ocr_result(result)    def update_review_item_from_qml(self, item_id: str, updates: Dict) -> bool:        """从qml更新审阅项"""        return self.update_review_item(item_id, updates)    def delete_review_item_from_qml(self, item_id: str):        """从qml删除审阅项"""        self.delete_review_item(item_id)    def batch_update_items_from_qml(self, item_ids: List[str], updates: Dict):        """从qml批量更新审阅项"""        self.batch_update_items(item_ids, updates)    def batch_delete_items_from_qml(self, item_ids: List[str]):        """从qml批量删除审阅项"""        self.batch_delete_items(item_ids)    def export_as_markdown_from_qml(self, items: List[Dict], export_path: str) -> bool:        """从qml导出为Markdown报告"""        return self.export_as_markdown(items, export_path)    def export_as_html_from_qml(self, items: List[Dict], export_path: str) -> bool:        """从qml导出为HTML报告"""        return self.export_as_html(items, export_path)    def set_filter(self, filters: Dict):        """设置过滤条件"""        self.current_filter = filters    def set_sort(self, sort_key: str, sort_order: str):        """设置排序条件"""        self.current_sort = (sort_key, sort_order)